package com.tilkicraft.tags;

import java.io.*;
import java.util.*;

/**
 * Client text widths for the TilkiCraft pack, so TAB names can be padded to one
 * fixed width. ASCII advances come from the pack's ASCII atlas; badge advances are
 * generated by tools/BuildTagsPack.java. Other characters are estimated.
 */
public final class TextWidth {
    // Advances for ' '..'~' measured from overlay/assets/minecraft/textures/font/ascii.png.
    private static final String ASCII = "42466662444626266666666666225656766666666466666666666666666464663666665662653666666646666664247";
    private static final Map<Character,Integer> GLYPHS = new HashMap<>();
    static final char PAD = '';
    static {
        Properties widths = new Properties();
        try (InputStream in = TextWidth.class.getResourceAsStream("/badge-widths.properties")) {
            if (in != null) widths.load(in);
        } catch (IOException ignored) { }
        widths.forEach((key, value) -> GLYPHS.put((char)Integer.parseInt((String)key), Integer.parseInt((String)value)));
    }
    private TextWidth() {}

    public static int width(String text) {
        int width = 0; boolean bold = false;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '§' && i + 1 < text.length()) {
                char code = Character.toLowerCase(text.charAt(++i));
                if (code == 'l') bold = true; else if ("0123456789abcdefrx".indexOf(code) >= 0) bold = false;
                continue;
            }
            int advance = advance(c);
            width += advance + (bold && advance > 0 && GLYPHS.get(c) == null ? 1 : 0);
        }
        return width;
    }

    static int advance(char c) {
        if (c >= 32 && c < 127) return ASCII.charAt(c - 32) - '0';
        Integer glyph = GLYPHS.get(c);
        if (glyph != null) return glyph;
        if (c >= PAD && c < PAD + 8) return 1 << (c - PAD);
        return switch (c) { case 'ı' -> 2; case 'İ' -> 4; case '▪', '•' -> 4; case '»' -> 6; default -> 6; };
    }

    /** Invisible padding of exactly the given width. */
    public static String pad(int pixels) {
        StringBuilder out = new StringBuilder();
        for (int bit = 7; bit >= 0; bit--) while (pixels >= (1 << bit)) { out.append((char)(PAD + bit)); pixels -= 1 << bit; }
        return out.toString();
    }

    /** Cuts the text (keeping colour codes) until it fits, marking the cut with "..". */
    public static String fit(String text, int pixels) {
        if (width(text) <= pixels) return text;
        StringBuilder fitted = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == '§' && i + 1 < text.length()) { fitted.append(c).append(text.charAt(++i)); continue; }
            if (width(fitted.toString() + c + "..") > pixels) break;
            fitted.append(c);
        }
        return fitted + "..";
    }
}
